1	{
2	  "$schema": "https://json-schema.org/draft/2020-12/schema",
3	  "$id": "debate-handoff.json",
4	  "title": "Debate Handoff Schema",
5	  "description": "Schema for inter-agent debate protocol. Tracks positions, challenges, and consensus across rounds.",
6	  "type": "object",
7	  "required": ["schema_version", "debate_id", "trigger", "round", "positions"],
8	  "properties": {
9	    "schema_version": {
10	      "type": "string",
11	      "const": "1.0.0"
12	    },
13	    "debate_id": {
14	      "type": "string",
15	      "pattern": "^debate-[0-9]{6}-[0-9]{4,6}$",
16	      "description": "Format: debate-YYMMDD-HHMM or debate-YYMMDD-HHMMSS"
17	    },
18	    "trigger": {
19	      "type": "string",
20	      "enum": ["allocation_request", "model_pivot", "agent_disagreement", "manual", "high_stakes"],
21	      "description": "What initiated the debate"
22	    },
23	    "trigger_context": {
24	      "type": "object",
25	      "description": "Context data for the trigger",
26	      "properties": {
27	        "amount": { "type": "number" },
28	        "channel": { "type": "string" },
29	        "session_id": { "type": "string" },
30	        "requesting_agent": { "type": "string" }
31	      }
32	    },
33	    "round": {
34	      "type": "integer",
35	      "minimum": 1,
36	      "maximum": 3,
37	      "description": "Current debate round (1=positions, 2=challenges, 3=final)"
38	    },
39	    "status": {
40	      "type": "string",
41	      "enum": ["collecting_positions", "challenge_phase", "final_positions", "consensus_reached", "timed_out"],
42	      "description": "Current debate status"
43	    },
44	    "positions": {
45	      "type": "array",
46	      "description": "Agent positions for current round",
47	      "items": {
48	        "type": "object",
49	        "required": ["agent", "position", "confidence"],
50	        "properties": {
51	          "agent": {
52	            "type": "string",
53	            "enum": ["capital-controller", "customer-finder", "self-corrector", "decision-maker"],
54	            "description": "Agent submitting position"
55	          },
56	          "position": {
57	            "type": "string",
58	            "enum": ["APPROVE", "REJECT", "MODIFY"],
59	            "description": "Agent's position on the decision"
60	          },
61	          "confidence": {
62	            "type": "number",
63	            "minimum": 0,
64	            "maximum": 1,
65	            "description": "Confidence level (must be >= 0.5 to participate)"
66	          },
67	          "ci_95": {
68	            "type": "array",
69	            "items": { "type": "number" },
70	            "minItems": 2,
71	            "maxItems": 2,
72	            "description": "95% credible interval [low, high]"
73	          },
74	          "evidence": {
75	            "type": "array",
76	            "items": { "type": "string" },
77	            "description": "Evidence supporting position"
78	          },
79	          "assumptions": {
80	            "type": "array",
81	            "items": { "type": "string" },
82	            "description": "Stated assumptions"
83	          },
84	          "round_submitted": {
85	            "type": "integer",
86	            "description": "Which round this position was submitted"
87	          },
88	          "updated_from": {
89	            "type": "string",
90	            "enum": ["APPROVE", "REJECT", "MODIFY"],
91	            "description": "Previous position if changed"
92	          }
93	        }
94	      }
95	    },
96	    "challenges": {
97	      "type": "array",
98	      "description": "Challenges raised during round 2",
99	      "items": {
100	        "type": "object",
101	        "required": ["challenger", "challenged", "assumption", "challenge_text"],
102	        "properties": {
103	          "challenger": {
104	            "type": "string",
105	            "description": "Agent raising the challenge"
106	          },
107	          "challenged": {
108	            "type": "string",
109	            "description": "Agent being challenged"
110	          },
111	          "assumption": {
112	            "type": "string",
113	            "description": "Specific assumption being challenged"
114	          },
115	          "challenge_text": {
116	            "type": "string",
117	            "description": "Challenge explanation"
118	          },
119	          "response": {
120	            "type": "string",
121	            "description": "Challenged agent's response"
122	          },
123	          "resolution": {
124	            "type": "string",
125	            "enum": ["defended", "conceded", "acknowledged", "no_response"],
126	            "description": "How the challenge was resolved"
127	          }
128	        }
129	      }
130	    },
131	    "consensus": {
132	      "type": "object",
133	      "description": "Final consensus result (populated after round 3)",
134	      "properties": {
135	        "score": {
136	          "type": "number",
137	          "minimum": 0,
138	          "maximum": 1,
139	          "description": "Weighted consensus score"
140	        },
141	        "decision": {
142	          "type": "string",
143	          "enum": ["APPROVE", "REJECT", "MODIFY"],
144	          "description": "Final consensus decision"
145	        },
146	        "unanimous": {
147	          "type": "boolean",
148	          "description": "Whether all agents agreed"
149	        },
150	        "total_confidence": {
151	          "type": "number",
152	          "description": "Sum of all confidence weights"
153	        },
154	        "method": {
155	          "type": "string",
156	          "const": "bayesian_weighted_average"
157	        }
158	      }
159	    },
160	    "dissents": {
161	      "type": "array",
162	      "description": "Agents whose positions differed significantly from consensus",
163	      "items": {
164	        "type": "object",
165	        "properties": {
166	          "agent": { "type": "string" },
167	          "position": { "type": "string" },
168	          "distance_from_consensus": { "type": "number" },
169	          "reasoning": { "type": "string" }
170	        }
171	      }
172	    },
173	    "timing": {
174	      "type": "object",
175	      "properties": {
176	        "started_at": {
177	          "type": "string",
178	          "format": "date-time"
179	        },
180	        "round_1_completed": {
181	          "type": "string",
182	          "format": "date-time"
183	        },
184	        "round_2_completed": {
185	          "type": "string",
186	          "format": "date-time"
187	        },
188	        "round_3_completed": {
189	          "type": "string",
190	          "format": "date-time"
191	        },
192	        "total_duration_ms": {
193	          "type": "integer"
194	        }
195	      }
196	    },
197	    "metadata": {
198	      "type": "object",
199	      "properties": {
200	        "forced_devils_advocate": {
201	          "type": "boolean",
202	          "description": "True if >90% initial consensus triggered devil's advocate"
203	        },
204	        "timed_out": {
205	          "type": "boolean"
206	        },
207	        "rounds_completed": {
208	          "type": "integer"
209	        }
210	      }
211	    }
212	  }
213	}
